  "color-variant": "'use client';\n\nimport React from 'react';\nimport { Button, ConfigProvider, Flex } from '@ceebee/ui/client';\nimport { useResponsive } from 'antd-style';\n\nconst App: React.FC = () => {\n  const { xxl } = useResponsive();\n\n  return (\n    <ConfigProvider componentSize={xxl ? 'medium' : 'small'}>\n      <Flex vertical gap=\"small\">\n        <Flex gap=\"small\" wrap>\n          <Button color=\"default\" variant=\"solid\">\n            Solid\n          </Button>\n          <Button color=\"default\" variant=\"outlined\">\n            Outlined\n          </Button>\n          <Button color=\"default\" variant=\"dashed\">\n            Dashed\n          </Button>\n          <Button color=\"default\" variant=\"filled\">\n            Filled\n          </Button>\n          <Button color=\"default\" variant=\"text\">\n            Text\n          </Button>\n          <Button color=\"default\" variant=\"link\">\n            Link\n          </Button>\n        </Flex>\n        <Flex gap=\"small\" wrap>\n          <Button color=\"primary\" variant=\"solid\">\n            Solid\n          </Button>\n          <Button color=\"primary\" variant=\"outlined\">\n            Outlined\n          </Button>\n          <Button color=\"primary\" variant=\"dashed\">\n            Dashed\n          </Button>\n          <Button color=\"primary\" variant=\"filled\">\n            Filled\n          </Button>\n          <Button color=\"primary\" variant=\"text\">\n            Text\n          </Button>\n          <Button color=\"primary\" variant=\"link\">\n            Link\n          </Button>\n        </Flex>\n        <Flex gap=\"small\" wrap>\n          <Button color=\"danger\" variant=\"solid\">\n            Solid\n          </Button>\n          <Button color=\"danger\" variant=\"outlined\">\n            Outlined\n          </Button>\n          <Button color=\"danger\" variant=\"dashed\">\n            Dashed\n          </Button>\n          <Button color=\"danger\" variant=\"filled\">\n            Filled\n          </Button>\n          <Button color=\"danger\" variant=\"text\">\n            Text\n          </Button>\n          <Button color=\"danger\" variant=\"link\">\n            Link\n          </Button>\n        </Flex>\n        <Flex gap=\"small\" wrap>\n          <Button color=\"pink\" variant=\"solid\">\n            Solid\n          </Button>\n          <Button color=\"pink\" variant=\"outlined\">\n            Outlined\n          </Button>\n          <Button color=\"pink\" variant=\"dashed\">\n            Dashed\n          </Button>\n          <Button color=\"pink\" variant=\"filled\">\n            Filled\n          </Button>\n          <Button color=\"pink\" variant=\"text\">\n            Text\n          </Button>\n          <Button color=\"pink\" variant=\"link\">\n            Link\n          </Button>\n        </Flex>\n        <Flex gap=\"small\" wrap>\n          <Button color=\"purple\" variant=\"solid\">\n            Solid\n          </Button>\n          <Button color=\"purple\" variant=\"outlined\">\n            Outlined\n          </Button>\n          <Button color=\"purple\" variant=\"dashed\">\n            Dashed\n          </Button>\n          <Button color=\"purple\" variant=\"filled\">\n            Filled\n          </Button>\n          <Button color=\"purple\" variant=\"text\">\n            Text\n          </Button>\n          <Button color=\"purple\" variant=\"link\">\n            Link\n          </Button>\n        </Flex>\n        <Flex gap=\"small\" wrap>\n          <Button color=\"cyan\" variant=\"solid\">\n            Solid\n          </Button>\n          <Button color=\"cyan\" variant=\"outlined\">\n            Outlined\n          </Button>\n          <Button color=\"cyan\" variant=\"dashed\">\n            Dashed\n          </Button>\n          <Button color=\"cyan\" variant=\"filled\">\n            Filled\n          </Button>\n          <Button color=\"cyan\" variant=\"text\">\n            Text\n          </Button>\n          <Button color=\"cyan\" variant=\"link\">\n            Link\n          </Button>\n        </Flex>\n      </Flex>\n    </ConfigProvider>\n  );\n};\n\nexport default App;\n\n",
  "custom-disabled-bg": "'use client';\n\nimport React from 'react';\nimport { Button, ConfigProvider, Flex } from '@ceebee/ui/client';\n\nconst App: React.FC = () => (\n  <Flex gap=\"small\" wrap>\n    <ConfigProvider\n      theme={{\n        components: {\n          Button: {\n            defaultBgDisabled: 'rgba(0,0,0,0.1)',\n            dashedBgDisabled: 'rgba(0,0,0,0.4)',\n          },\n        },\n      }}\n    >\n      <Button type=\"primary\" disabled>\n        Primary Button\n      </Button>\n      <Button disabled>Default Button</Button>\n      <Button type=\"dashed\" disabled>\n        Dashed Button\n      </Button>\n    </ConfigProvider>\n  </Flex>\n);\n\nexport default App;\n\n",
